vulnerable:
static int session_get_port(struct session *s)
{
    struct conn *c = session_find_conn(s);
    return c->port;
}

fixed:
static int session_get_port(struct session *s)
{
    struct conn *c = session_find_conn(s);
    if (c == NULL)
        return -1;
    return c->port;
}

